const dishes = [
  { id: 1, name: "Party jollof", price: 3500, category: "Rice" },
  { id: 2, name: "Fried rice", price: 3500, category: "Rice" },
  { id: 3, name: "Egusi + pounded yam", price: 4500, category: "Soups" },
  { id: 4, name: "Pepper soup", price: 3000, category: "Soups" },
  { id: 5, name: "Fried plantain", price: 1200, category: "Sides" },
  { id: 6, name: "Moi moi", price: 1000, category: "Sides" },
]

function AllDishes() {
  return (
    <ul className="all">
      {dishes.map((dish) => (
        <li key={dish.id}>{dish.name}: ₦{dish.price.toLocaleString()}</li>
      ))}
    </ul>
  )
}

function Category({ name }) {
  const items = dishes.filter((d) => d.category === name)
  return (
    <section>
      <h2>{name}</h2>
      {items.length === 0 && <p className="empty">Nothing here today</p>}
      <ul>
        {items.map((d) => <li key={d.id}>{d.name}</li>)}
      </ul>
    </section>
  )
}

function App() {
  const categories = [...new Set(dishes.map((d) => d.category))]
  return (
    <main>
      <AllDishes />
      {categories.map((c) => <Category key={c} name={c} />)}
      <Category name="Drinks" />
    </main>
  )
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />)
